import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { screen, render } from "@testing-library/react";
import { KpiDetailSection } from "../index";
describe("KpiDetailSection", () => {
    it("handles VALUE_CHANGE variant details", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { previousValue: 8, value: 5, variant: "VALUE_CHANGE" }));
        expect(baseElement.textContent).toEqual("3");
    });
    it("handles VALUE_CHANGE_AS_PERCENTAGE variant details", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { previousValue: 8, value: 5, variant: "VALUE_CHANGE_AS_PERCENTAGE" }));
        expect(baseElement.textContent).toEqual("3%");
    });
    it("handles CAPTION variant details", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { label: "att", variant: "CAPTION" }));
        expect(baseElement.textContent).toEqual("att");
    });
    it("handles ATTRIBUTE variant details", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { label: "att", value: 5, variant: "ATTRIBUTE" }));
        expect(baseElement.textContent).toEqual("att5");
    });
    it("handles PERCENTAGE_CHANGE variant details", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { previousValue: 8, value: 5, variant: "PERCENTAGE_CHANGE" }));
        expect(baseElement.textContent).toEqual("37.5% (-3)");
    });
    it("handles VALUE_AND_PERCENTAGE_CHANGE variant details", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { previousValue: 8, value: 5, variant: "VALUE_AND_PERCENTAGE_CHANGE" }));
        // the 537.5% is value 5 - 37.5 % change
        expect(baseElement.textContent).toEqual("537.5% (-3)");
    });
    it("uses valueFormatter", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { label: "att", value: 5, valueFormatter: (val) => `${val} unit`, variant: "ATTRIBUTE" }));
        expect(baseElement.textContent).toEqual("att5 unit");
    });
    it("does not show anything when previous value is missing", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { value: 15, variant: "PERCENTAGE_CHANGE" }));
        expect(baseElement.textContent).toEqual("");
    });
    it("shows up arrow when there previous value is 0", () => {
        render(_jsx(KpiDetailSection, { previousValue: 0, value: 15, variant: "PERCENTAGE_CHANGE" }));
        expect(screen.getByTestId("ArrowStrokedUpIcon")).toBeTruthy();
    });
    it("shows up arrow when value increases", () => {
        render(_jsx(KpiDetailSection, { previousValue: 8, value: 15, variant: "PERCENTAGE_CHANGE" }));
        expect(screen.getByTestId("ArrowStrokedUpIcon")).toBeTruthy();
    });
    it("shows down arrow when value decreases", () => {
        render(_jsx(KpiDetailSection, { previousValue: 8, value: 5, variant: "PERCENTAGE_CHANGE" }));
        expect(screen.getByTestId("ArrowStrokedDownIcon")).toBeTruthy();
    });
    it("uses success color for down arrow when successDelta is LESS_THAN", () => {
        render(_jsx(KpiDetailSection, { previousValue: 8, successDelta: "LESS_THAN", value: 5, variant: "PERCENTAGE_CHANGE" }));
        expect(screen.getByTestId("ArrowStrokedDownIcon")).toHaveClass("MuiSvgIcon-colorSuccess");
    });
    it("uses error color for up arrow when successDelta is LESS_THAN", () => {
        render(_jsx(KpiDetailSection, { previousValue: 8, successDelta: "LESS_THAN", value: 15, variant: "PERCENTAGE_CHANGE" }));
        expect(screen.getByTestId("ArrowStrokedUpIcon")).toHaveClass("MuiSvgIcon-colorError");
    });
    it("uses success color for up arrow when successDelta is GREATER_THAN", () => {
        render(_jsx(KpiDetailSection, { previousValue: 8, successDelta: "GREATER_THAN", value: 15, variant: "PERCENTAGE_CHANGE" }));
        expect(screen.getByTestId("ArrowStrokedUpIcon")).toHaveClass("MuiSvgIcon-colorSuccess");
    });
    it("uses error color for down arrow when successDelta is GREATER_THAN", () => {
        render(_jsx(KpiDetailSection, { previousValue: 8, successDelta: "GREATER_THAN", value: 5, variant: "PERCENTAGE_CHANGE" }));
        expect(screen.getByTestId("ArrowStrokedDownIcon")).toHaveClass("MuiSvgIcon-colorError");
    });
    it("shows no change when value is the same", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { previousValue: 15, value: 15, variant: "PERCENTAGE_CHANGE" }));
        expect(baseElement.textContent).toEqual("No change");
    });
    it("shows no change when both values are 0", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { previousValue: 0, value: 0, variant: "PERCENTAGE_CHANGE" }));
        expect(baseElement.textContent).toEqual("No change");
    });
    it("uses label if present", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { label: "label", previousValue: 2, value: 4, variant: "PERCENTAGE_CHANGE" }));
        expect(baseElement.textContent).toEqual("100% (+2)label");
    });
    it("uses legend if present", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { legend: "legend", previousValue: 2, value: 4, variant: "PERCENTAGE_CHANGE" }));
        expect(baseElement.textContent).toEqual("legend100% (+2)");
    });
    it("does not show anything if the variant is undefined", () => {
        const { baseElement } = render(_jsx(KpiDetailSection, { previousValue: 2, value: 4, variant: undefined }));
        expect(baseElement.textContent).toEqual("");
    });
});
